*epsilon.^3.*r.*RR.*sin(2.*omega).*cos((-1 + kp).*omega).*1 + 2.*epsilon.^3.*r.*RR.*t2.*sin(2.*omega).*cos((-1 + kp).*omega).*1 - 4.*epsilon.*r.*RR.*1.*sin((-1 + kp).*omega) + 4.*dbetapardB0.*epsilon.^3.*r.*RR.*1.*sin((-1 + kp).*omega) - 4.*epsilon.^3.*r.*RR.*t2.*1.*sin((-1 + kp).*omega) + 2.*epsilon.*r.*RR.*cos(2.*omega).*1.*sin((-1 + kp).*omega) - 2.*dbetapardB0.*epsilon.^3.*r.*RR.*cos(2.*omega).*1.*sin((-1 + kp).*omega) + 2.*epsilon.^3.*r.*RR.*t2.*cos(2.*omega).*1.*sin((-1 + kp).*omega)).*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3)) + 2.*epsilon.*sum((-1 + ms).*cos((-1 + ms).*omega).*S,3).*(r.^2.*(-4.*epsilon.*r.*RR.*cos((-1 + kp).*omega).*1 + 4.*dbetapardB0.*epsilon.^3.*r.*RR.*cos((-1 + kp).*omega).*1 - 4.*epsilon.^3.*r.*RR.*t2.*cos((-1 + kp).*omega).*1 - 2.*epsilon.*r.*RR.*cos(2.*omega).*cos((-1 + kp).*omega).*1 + 2.*dbetapardB0.*epsilon.^3.*r.*RR.*cos(2.*omega).*cos((-1 + kp).*omega).*1 - 2.*epsilon.^3.*r.*RR.*t2.*cos(2.*omega).*cos((-1 + kp).*omega).*1 + 2.*epsilon.*r.*RR.*sin(2.*omega).*1.*sin((-1 + kp).*omega) - 2.*dbetapardB0.*epsilon.^3.*r.*RR.*sin(2.*omega).*1.*sin((-1 + kp).*omega) + 2.*epsilon.^3.*r.*RR.*t2.*sin(2.*omega).*1.*sin((-1 + kp).*omega)) + epsilon.^2.*r.*T145.*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3) + epsilon.^2.*(-2.*epsilon.*r.*RR.*cos((-1 + kp).*omega).*1 + 2.*dbetapardB0.*epsilon.^3.*r.*RR.*cos((-1 + kp).*omega).*1 - 2.*epsilon.^3.*r.*RR.*t2.*cos((-1 + kp).*omega).*1).*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3).^2) + epsilon.^2.*P.*(12.*epsilon.*r.^3.*RR.*cos(omega).*cos((-1 + kp).*omega).*1 - 12.*dbetapardB0.*epsilon.^3.*r.^3.*RR.*cos(omega).*cos((-1 + kp).*omega).*1 + 12.*epsilon.^3.*r.^3.*RR.*t2.*cos(omega).*cos((-1 + kp).*omega).*1 + epsilon.^3.*T146.*sum((-1 + ms).*cos((-1 + ms).*omega).*S,3).^2 - 12.*epsilon.*r.^3.*RR.*sin(omega).*1.*sin((-1 + kp).*omega) + 12.*dbetapardB0.*epsilon.^3.*r.^3.*RR.*sin(omega).*1.*sin((-1 + kp).*omega) - 12.*epsilon.^3.*r.^3.*RR.*t2.*sin(omega).*1.*sin((-1 + kp).*omega) - 8.*epsilon.^2.*r.^2.*RR.*sin(2.*omega).*cos((-1 + kp).*omega).*1.*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3) + 8.*dbetapardB0.*epsilon.^4.*r.^2.*RR.*sin(2.*omega).*cos((-1 + kp).*omega).*1.*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3) - 8.*epsilon.^4.*r.^2.*RR.*t2.*sin(2.*omega).*cos((-1 + kp).*omega).*1.*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3) + 16.*epsilon.^2.*r.^2.*RR.*1.*sin((-1 + kp).*omega).*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3) - 16.*dbetapardB0.*epsilon.^4.*r.^2.*RR.*1.*sin((-1 + kp).*omega).*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3) + 16.*epsilon.^4.*r.^2.*RR.*t2.*1.*sin((-1 + kp).*omega).*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3) - 8.*epsilon.^2.*r.^2.*RR.*cos(2.*omega).*1.*sin((-1 + kp).*omega).*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3) + 8.*dbetapardB0.*epsilon.^4.*r.^2.*RR.*cos(2.*omega).*1.*sin((-1 + kp).*omega).*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3) - 8.*epsilon.^4.*r.^2.*RR.*t2.*cos(2.*omega).*1.*sin((-1 + kp).*omega).*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3) + 4.*epsilon.^3.*r.*RR.*cos(omega).*cos((-1 + kp).*omega).*1.*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3).^2 - 4.*dbetapardB0.*epsilon.^5.*r.*RR.*cos(omega).*cos((-1 + kp).*omega).*1.*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3).^2 + 4.*epsilon.^5.*r.*RR.*t2.*cos(omega).*cos((-1 + kp).*omega).*1.*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3).^2 - 12.*epsilon.^3.*r.*RR.*sin(omega).*1.*sin((-1 + kp).*omega).*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3).^2 + 12.*dbetapardB0.*epsilon.^5.*r.*RR.*sin(omega).*1.*sin((-1 + kp).*omega).*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3).^2 - 12.*epsilon.^5.*r.*RR.*t2.*sin(omega).*1.*sin((-1 + kp).*omega).*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3).^2 + 2.*epsilon.*sum((-1 + ms).*cos((-1 + ms).*omega).*S,3).*(-2.*epsilon.*r.*T147 + epsilon.^2.*T145.*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3)))))./(q.^2.*RR.^2);
		j33kpF_FFT = real(fft(j33kpF, [], 2)) / Ntheta;
		jacTotal(3, 3 + Nb + (kp - 1), rowsF, :) = reshape(j33kpF_FFT(:, mF+1).', [1,1,nmF, Nq]);

	end

	% --- resP ---
	gamma = 3;
	jacTotal(1,2, gamma, :) = mean(-(T114./RR.^2), 2);
	jacTotal(1,3, gamma, :) = mean((-RR - epsilon.^2.*Pp.*RR + deltap.*epsilon.*RR.*cos(omega) + epsilon.*T114.*cos(omega) - epsilon.*RR.*cos(omega).*sum(cos((-1 + ms).*omega).*Sp,3) + epsilon.*RR.*sin(omega).*sum(sin((-1 + ms).*omega).*Sp,3))./RR.^2, 2);
	jacTotal(2,2, gamma, :) = mean((epsilon.^2.*P.*cos(omega) + r.*cos(omega) - epsilon.*sum((-1 + ms).*cos((-1 + ms).*omega).*S,3))./(epsilon.*RR), 2);
	jacTotal(2,3, gamma, :) = mean((-(epsilon.^2.*P) - r + epsilon.*cos(omega).*sum((-1 + ms).*cos((-1 + ms).*omega).*S,3) + epsilon.*sin(omega).*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3))./RR, 2);
	for kp = 2:(Ns+1)
        T142 = -((-1 + kp).*cos((-1 + kp).*omega).*1.*(-(deltap.*epsilon) + cos(omega) + epsilon.^2.*Pp.*cos(omega) + epsilon.*sum(cos((-1 + ms).*omega).*Sp,3))) - -((-1 + kp).*1.*sin((-1 + kp).*omega)).*(sin(omega) + epsilon.^2.*Pp.*sin(omega) - epsilon.*sum(sin((-1 + ms).*omega).*Sp,3));
		jacTotal(1, 3 + Nb + (kp - 1), gamma, :) = mean((-(RR.*T142) + epsilon.*T114.*cos((-1 + kp).*omega).*1)./(epsilon.*RR.^2), 2);
		jacTotal(2, 3 + Nb + (kp - 1), gamma, :) = mean((-(cos((-1 + kp).*omega).*1.*(epsilon.^2.*P.*cos(omega) + r.*cos(omega) - epsilon.*sum((-1 + ms).*cos((-1 + ms).*omega).*S,3))) + 1.*sin((-1 + kp).*omega).*(epsilon.^2.*P.*sin(omega) + r.*sin(omega) - epsilon.*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3)))./(epsilon.*RR), 2);
	end

	% --- resB modes ---
	j11B = (2.*epsilon.*(1 - dbetapardB0.*epsilon.^2 + epsilon.^2.*t2).*(-(BB.^2./(BB - dbetapardB.*epsilon.^2).^2) - (epsilon.^2.*r.^2.*T2.*T5)./q.^2))./RR.^2;
	j11B_FFT = real(fft(j11B, [], 2)) / Ntheta;
	jacTotal(1,1, rowsB, :) = reshape(j11B_FFT(:, mB+1).', [1,1,nmB, Nq]);

	j12B = (2.*epsilon.*(1 - dbetapardB0.*epsilon.^2 + epsilon.^2.*t2).^2.*(-((BB.^2.*(BB - dbetapardB.*epsilon.^2 - d2betapardRdB.*epsilon.^2.*RR))./(BB - dbetapardB.*epsilon.^2).^3) - (epsilon.^2.*r.^2.*T2.*T5)./q.^2))./RR.^3;
	j12B_FFT = real(fft(j12B, [], 2)) / Ntheta;
	jacTotal(1,2, rowsB, :) = reshape(j12B_FFT(:, mB+1).', [1,1,nmB, Nq]);

	j13B = (2.*(epsilon - dbetapardB0.*epsilon.^3 + epsilon.^3.*t2).^2.*((BB.^2.*(BB - dbetapardB.*epsilon.^2 - d2betapardRdB.*epsilon.^2.*RR).*cos(omega))./(BB - dbetapardB.*epsilon.^2).^3 + (epsilon.^2.*r.^2.*T2.*T5.*cos(omega))./q.^2 - (epsilon.*r.^2.*RR.*T2.*(epsilon.^2.*P + r - epsilon.*cos(omega).*sum((-1 + ms).*cos((-1 + ms).*omega).*S,3) - epsilon.*sin(omega).*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3)))./q.^2 + (epsilon.*r.^2.*RR.*T5.*T9.*(1 + epsilon.^2.*Pp - deltap.*epsilon.*cos(omega) + epsilon.*cos(omega).*sum(cos((-1 + ms).*omega).*Sp,3) - epsilon.*sin(omega).*sum(sin((-1 + ms).*omega).*Sp,3)))./q.^2))./RR.^3;
	j13B_FFT = real(fft(j13B, [], 2)) / Ntheta;
	jacTotal(1,3, rowsB, :) = reshape(j13B_FFT(:, mB+1).', [1,1,nmB, Nq]);

	j22B = (-2.*epsilon.^2.*r.^2.*(1 - dbetapardB0.*epsilon.^2 + epsilon.^2.*t2).^2.*T5.*T9.*(epsilon.^2.*P.*cos(omega) + r.*cos(omega) - epsilon.*sum((-1 + ms).*cos((-1 + ms).*omega).*S,3)))./(q.^2.*RR.^2);
	j22B_FFT = real(fft(j22B, [], 2)) / Ntheta;
	jacTotal(2,2, rowsB, :) = reshape(j22B_FFT(:, mB+1).', [1,1,nmB, Nq]);

	j23B = (2.*epsilon.^3.*r.^2.*(1 - dbetapardB0.*epsilon.^2 + epsilon.^2.*t2).^2.*T5.*T9.*(epsilon.^2.*P + r - epsilon.*cos(omega).*sum((-1 + ms).*cos((-1 + ms).*omega).*S,3) - epsilon.*sin(omega).*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3)))./(q.^2.*RR.^2);
	j23B_FFT = real(fft(j23B, [], 2)) / Ntheta;
	jacTotal(2,3, rowsB, :) = reshape(j23B_FFT(:, mB+1).', [1,1,nmB, Nq]);

	% derivatives wrt B_l (bundle)
	for lp = 0:Nb-1
        j13lpB = 2.*BB.*(1 - (BB.*(-1 + d2betapardB2.*epsilon.^2).*(1 - dbetapardB0.*epsilon.^2 + epsilon.^2.*t2).^2)./((BB - dbetapardB.*epsilon.^2).^3.*RR.^2) - (1 - dbetapardB0.*epsilon.^2 + epsilon.^2.*t2).^2./((BB - dbetapardB.*epsilon.^2).^2.*RR.^2)).*cos(lp.*omega);
		j13lpB_FFT = real(fft(j13lpB, [], 2)) / Ntheta;
		jacTotal(1, 3+lp+1, rowsB, :) = reshape(j13lpB_FFT(:, mB+1).', [1,1,nmB, Nq]);
	end

	% derivatives wrt S_k (bundle), k=2..Ns+1
	for kp = 2:(Ns+1)
        T112 = cos((-1 + kp).*omega).*1.*(epsilon.^2.*P.*cos(omega) + r.*cos(omega) - epsilon.*sum((-1 + ms).*cos((-1 + ms).*omega).*S,3)) - 1.*sin((-1 + kp).*omega).*(epsilon.^2.*P.*sin(omega) + r.*sin(omega) - epsilon.*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3));
        T113 = -((-1 + kp).*cos((-1 + kp).*omega).*1.*(-(deltap.*epsilon) + cos(omega) + epsilon.^2.*Pp.*cos(omega) + epsilon.*sum(cos((-1 + ms).*omega).*Sp,3))) - -((-1 + kp).*1.*sin((-1 + kp).*omega)).*(sin(omega) + epsilon.^2.*Pp.*sin(omega) - epsilon.*sum(sin((-1 + ms).*omega).*Sp,3));
    	T128 = -2.*((-1 + kp).*cos((-1 + kp).*omega).*1.*(epsilon.^2.*P.*cos(omega) + r.*cos(omega) - epsilon.*sum((-1 + ms).*cos((-1 + ms).*omega).*S,3)) + -((-1 + kp).*1.*sin((-1 + kp).*omega)).*(epsilon.^2.*P.*sin(omega) + r.*sin(omega) - epsilon.*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3)));
        j13kpB = (epsilon.*(1 - dbetapardB0.*epsilon.^2 + epsilon.^2.*t2).^2.*((2.*BB.^2.*(BB - dbetapardB.*epsilon.^2 - d2betapardRdB.*epsilon.^2.*RR).*cos((-1 + kp).*omega).*1)./(BB - dbetapardB.*epsilon.^2).^3 + (epsilon.*r.^2.*(-(RR.*T128.*T2) + 2.*RR.*T113.*T5.*T9 + 2.*epsilon.*T2.*T5.*cos((-1 + kp).*omega).*1))./q.^2))./RR.^3;
		j13kpB_FFT = real(fft(j13kpB, [], 2)) / Ntheta;
		jacTotal(1, 3 + Nb + (kp - 1), rowsB, :) = reshape(j13kpB_FFT(:, mB+1).', [1,1,nmB, Nq]);
		j23kpB = (2.*epsilon.^2.*r.^2.*T112.*(1 - dbetapardB0.*epsilon.^2 + epsilon.^2.*t2).^2.*T5.*T9)./(q.^2.*RR.^2);
		j23kpB_FFT = real(fft(j23kpB, [], 2)) / Ntheta;
		jacTotal(2, 3 + Nb + (kp - 1), rowsB, :) = reshape(j23kpB_FFT(:, mB+1).', [1,1,nmB, Nq]);
	end
	%% Construct J
    totalDofs = dof_count * (3 + Nb) + (dof_count-1) *Ns;
    nCols = (3+ Nb + Ns)^2 * Nq;
    % precomputed: M_extended (totalDofs x nCols), P_templates{d} with fields i,j,v_template
    J = spalloc(totalDofs, totalDofs, 1 * nnz(M_extended));  % or a tighter nnz estimate

    for d = 1:3
        % Extract jacobian block and flatten in the SAME order P_templates was built.
        jac_d = squeeze(jacTotal(d,:,:,:));    % size: [nProfiles, nProfiles, Nq] (alpha,gamma,q)
        % permute to [q, gamma, alpha] then linearize -> ordering matches P_templates{d}.i
        jacTotal_flat = reshape(permute(jac_d, [3, 1, 2]), [], 1);   % length == nCols

        % Row-scale P template by jac values (this gives diag(jac)*P_extended)
        vP_scaled = P_templates{d}.v_template .* jacTotal_flat(P_templates{d}.i);

        % Create sparse scaled-P and accumulate J via M_extended * P_scaled
        P_scaled = sparse(P_templates{d}.i, P_templates{d}.j, vP_scaled, nCols, totalDofs);
        J = J + M_extended * P_scaled;
    end
end
